export function matchesQuery(item, query) {
  return item.name.includes(query);
}

visibleTest:
import assert from 'node:assert/strict';
import test from 'node:test';
import { matchesQuery } from '../src/search.js';

test('[TC-01] 名称精确匹配', () => {
  assert.equal(matchesQuery({ name: 'Alpha', code: 'A-01' }, 'Alpha'), true);
});

evaluatorTest:
import assert from 'node:assert/strict';
import test from 'node:test';
import { matchesQuery } from '../src/search.js';

test('搜索关键词归一化隐藏验收', () => {
  assert.equal(matchesQuery({ name: 'Alpha Team', code: 'A-01' }, ' alpha '), true);
  assert.equal(matchesQuery({ name: 'Alpha Team', code: 'A-01' }, 'a-01'), true);
  assert.equal(matchesQuery({ name: 'Alpha Team', code: 'A-01' }, 'BETA'), false);
  assert.equal(matchesQuery({ name: 'Alpha Team', code: 'A-01' }, '   '), true);
  assert.equal(matchesQuery({ name: null }, 'alpha'), false);
});

