initialSource:
export function pageWindow(total, page, pageSize) {
  return {
    page,
    totalPages: Math.ceil(total / pageSize),
    start: (page - 1) * pageSize + 1,
    end: Math.min(page * pageSize, total),
  };
}

visibleTest:
import assert from 'node:assert/strict';
import test from 'node:test';
import { pageWindow } from '../src/pagination.js';

test('[TC-01] 正常分页窗口', () => {
  assert.deepEqual(pageWindow(25, 2, 10), { page: 2, totalPages: 3, start: 11, end: 20 });
});

evaluatorTest:
import assert from 'node:assert/strict';
import test from 'node:test';
import { pageWindow } from '../src/pagination.js';

test('分页窗口隐藏验收', () => {
  assert.deepEqual(pageWindow(0, 9, 0), { page: 1, totalPages: 0, start: 0, end: 0 });
  assert.deepEqual(pageWindow(25, 99, 10), { page: 3, totalPages: 3, start: 21, end: 25 });
  assert.deepEqual(pageWindow(25, -2, 10), { page: 1, totalPages: 3, start: 1, end: 10 });
  assert.deepEqual(pageWindow(3.9, 1.8, 2.7), { page: 1, totalPages: 2, start: 1, end: 2 });
  assert.deepEqual(pageWindow(-5, 1, 10), { page: 1, totalPages: 0, start: 0, end: 0 });
});
